use crate::aap::caps::{http_client, notifier};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0xF) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment record for the input; best effort, does not affect the output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&composed.overview)
        );
        let _ = http_client::fetch(&url);

        let mut message = format!("{}\n{}", composed.date, composed.overview);
        for e in composed.entries.iter().filter(|e| e.kept) {
            message.push_str(&format!("\n- {} ({}): {}", e.title, e.link, e.summary));
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
